/** Payment charge endpoint. */

export interface ChargeRequest {
  tenant_id: string
  amount_cents: number
  currency: string
  customer_id: string
}

export function createCharge(req: ChargeRequest): { id: string; status: string } {
  if (!req.tenant_id || !req.tenant_id.trim()) throw new Error('tenant_id is required and must not be blank')
  if (req.amount_cents <= 0) throw new Error('amount_cents must be positive')
  return { id: `ch_${req.customer_id}`, status: 'succeeded' }
}

files.client/checkout.ts:
/** Checkout flow: calls the charge endpoint. */
import { createCharge } from '../api/charges.ts'

export interface Cart {
  total_cents: number
  customerId: string
  loyalty_points: number
}

export function submitCheckout(cart: Cart) {
  return createCharge({
    amount_cents: cart.total_cents,
    currency: 'usd',
    customer_id: cart.customerId,
    metadata: { loyalty_points: cart.loyalty_points },
  })
}

