files.api/charges.ts:
/** Payment charge endpoint. */

export interface ChargeRequest {
  amount_cents: number
  /**
   * Only 'usd' is supported. `createCharge` rejects any other currency string.
   *
   * This supersedes the earlier decision to accept any currency (previously
   * recorded in docs/billing.md#decisions): until a tenant billing profile
   * exists, the supported currency is hard-coded to 'usd' and the caller must
   * pass 'usd'.
   */
  currency: string
  customer_id: string
}

export function createCharge(req: ChargeRequest): { id: string; status: string } {
  if (req.amount_cents <= 0) throw new Error('amount_cents must be positive')
  if (req.currency !== 'usd') throw new Error(`currency must be 'usd', got '${req.currency}'`)
  return { id: `ch_${req.customer_id}`, status: 'succeeded' }
}

